import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"9.1 电力系统与低压配电概述","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-1-dian-li-xi-tong-yu-di-ya-pei-dian-gai-shu.md","filePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-1-dian-li-xi-tong-yu-di-ya-pei-dian-gai-shu.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-1-dian-li-xi-tong-yu-di-ya-pei-dian-gai-shu.md"};function r(l,t,s,d,h,g){return i(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="_9-1-电力系统与低压配电概述" tabindex="-1">9.1 电力系统与低压配电概述 <a class="header-anchor" href="#_9-1-电力系统与低压配电概述" aria-label="Permalink to &quot;9.1 电力系统与低压配电概述&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电从发电厂到你家插座,中间要经过&quot;发电、输电、变电、配电&quot;几大环节。这一节从整体看懂电力系统是怎么&quot;送电&quot;的,重点记住我国低压配电的基本形式:三相四线制 380V/220V。</p><h2 id="一、电力系统的组成" tabindex="-1">一、电力系统的组成 <a class="header-anchor" href="#一、电力系统的组成" aria-label="Permalink to &quot;一、电力系统的组成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发电厂 ──► 升压变电站 ──► 高压输电线路 ──► 降压变电站 ──► 低压配电线路 ──► 用户</span></span></code></pre></div><table tabindex="0"><thead><tr><th>环节</th><th>干什么</th><th>电压举例</th></tr></thead><tbody><tr><td><strong>发电</strong></td><td>把其他能量转成电能(火、水、风、核)</td><td>发电机出口 6.3kV、10.5kV</td></tr><tr><td><strong>输电</strong></td><td>高压远距离送电,损耗小</td><td>110kV、220kV、500kV</td></tr><tr><td><strong>变电</strong></td><td>升压送电、降压配用</td><td>降压到 10kV/6kV</td></tr><tr><td><strong>配电</strong></td><td>把电分送到各用电点</td><td>高压配电 10kV;低压配电 380/220V</td></tr><tr><td><strong>用电</strong></td><td>电能转换成动力、光、热</td><td>家用 220V,三相 380V</td></tr></tbody></table><blockquote><p>💡 <strong>为什么高压输电?</strong> 同样功率,P = UI,电压越高电流越小,线路损耗(与电流平方成正比)就越小。所以远距离输电都用高压。</p></blockquote><h2 id="二、高压与低压的划分" tabindex="-1">二、高压与低压的划分 <a class="header-anchor" href="#二、高压与低压的划分" aria-label="Permalink to &quot;二、高压与低压的划分&quot;">​</a></h2><p>按电压高低划分(我国习惯):</p><table tabindex="0"><thead><tr><th>分类</th><th>电压范围</th><th>说明</th></tr></thead><tbody><tr><td><strong>低压</strong></td><td><strong>1 kV(1000V)以下</strong></td><td>常见 380V / 220V,低压电工操作范围</td></tr><tr><td><strong>高压</strong></td><td>1 kV 以上</td><td>常见 10kV、35kV,需高压电工证</td></tr></tbody></table><blockquote><p>⚠️ 判断题常考:<strong>1kV(1000V)是低压与高压的分界线</strong>。低压电工只从事 1kV 以下电气设备操作。</p></blockquote><h2 id="三、我国低压配电的基本形式" tabindex="-1">三、我国低压配电的基本形式 <a class="header-anchor" href="#三、我国低压配电的基本形式" aria-label="Permalink to &quot;三、我国低压配电的基本形式&quot;">​</a></h2><h3 id="三相四线制-最常见" tabindex="-1">三相四线制(最常见) <a class="header-anchor" href="#三相四线制-最常见" aria-label="Permalink to &quot;三相四线制(最常见)&quot;">​</a></h3><ul><li><strong>三根相线</strong>(火线,旧标 A、B、C,现标 L1、L2、L3)+ **一根中性线(N 线);</li><li>相线之间是线电压 <strong>380V</strong>,相线与中性线之间是相电压 <strong>220V</strong>;</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 ─────</span></span>
<span class="line"><span>L2 ─────  线间 380V</span></span>
<span class="line"><span>L3 ─────</span></span>
<span class="line"><span>N  ─────  相线与N之间 220V</span></span></code></pre></div><ul><li>三相电动机接三相 380V;单相设备(照明、插座)接 220V(取一根相线 + 中性线)。</li></ul><blockquote><p>💡 记忆:<strong>&quot;三相四线,380/220&quot;</strong> 是低压配电的基本盘。</p></blockquote><h2 id="四、频率与电压质量" tabindex="-1">四、频率与电压质量 <a class="header-anchor" href="#四、频率与电压质量" aria-label="Permalink to &quot;四、频率与电压质量&quot;">​</a></h2><ul><li>我国工频(<strong>交流电频率</strong>)为 <strong>50 Hz</strong>;</li><li>供电质量三要素:<strong>电压、频率、波形</strong>符合规定;</li><li>对低压用户,电压偏差一般允许在额定值的一定范围内(如 ±7% 左右);电压过低叫<strong>欠压</strong>,过高叫<strong>过压</strong>,都影响设备安全。</li></ul><h2 id="五、一次回路与二次回路" tabindex="-1">五、一次回路与二次回路 <a class="header-anchor" href="#五、一次回路与二次回路" aria-label="Permalink to &quot;五、一次回路与二次回路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>回路</th><th>内容</th></tr></thead><tbody><tr><td><strong>一次回路(主电路)</strong></td><td>直接输送、分配电能的电路(母线、断路器、接触器主触点、电动机等)</td></tr><tr><td><strong>二次回路(辅助电路)</strong></td><td>控制、保护、测量、信号电路(按钮、继电器、仪表、指示灯等)</td></tr></tbody></table><blockquote><p>⚠️ 判断题常考:一次回路是<strong>大电流主电路</strong>;二次回路是<strong>小电流控制/保护电路</strong>,两者不要混。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 电力系统五环节:发、输、变、配、用。</li><li>✅ <strong>低压 = 1kV 以下</strong>,常见 380V/220V。</li><li>✅ 我国低压配电基本形式:<strong>三相四线制</strong>(L1/L2/L3 + N),线电压 380V、相电压 220V。</li><li>✅ 工频 <strong>50 Hz</strong>。</li><li>⚠️ 易混点:线电压(相线之间 380V)vs 相电压(相线与中性线 220V)。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>电要经过发、输、变、配、用才到用户,高压输电损耗小。</li><li>1kV 以下叫低压,是低压电工的作业范围。</li><li>三相四线制 380/220V,一次回路和二次回路职责不同。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)低压是指电压在 1kV 及以下。( )</li><li>(单选)我国低压配电系统采用的工频频率是()。 A. 60 Hz　B. 50 Hz　C. 100 Hz　D. 40 Hz</li><li>(判断)三相四线制中,相线与中性线之间的电压(相电压)为 220V。( )</li><li>(单选)远距离输电采用高压的主要原因是()。 A. 减少线路损耗　B. 更安全　C. 设备更便宜　D. 便于测量</li><li>(判断)一次回路是控制、保护、测量用的辅助电路。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。1kV(1000V)以下是低压。</li><li><strong>B</strong>。我国工频 50 Hz。</li><li><strong>√</strong>。相线对中性线为 220V,相线对相线为 380V。</li><li><strong>A</strong>。高压输电电流小,线路损耗小。</li><li><strong>×</strong>。一次回路是主电路,二次回路才是控制、保护、测量电路。</li></ol></details>`,29)])])}const u=a(e,[["render",r]]);export{p as __pageData,u as default};
